import type { PluginListenerHandle } from '@capacitor/core';

interface OneWelcomePlugin {
  authenticateUser(options: { userProfile: string; authenticator?: string }): Promise<{ token: string }>;
  addListener(eventName: 'onAuthStart' | 'onPinChallenge' | 'onBiometricChallenge' | 'onCustomAuthChallenge' | 'onAuthSuccess' | 'onAuthFailure', listenerFunc: (data: any) => void): Promise<PluginListenerHandle> & PluginListenerHandle;
  removeAllListeners(): Promise<void>;
}
```

