import Capacitor
import Onegini

@objc(OneWelcomePlugin)
public class OneWelcomePlugin: CAPPlugin, AuthenticationDelegate {

    private var pluginListener: PluginListener?

    @objc func authenticateUser(call: CAPPluginCall) {
        guard let userProfile = call.getString("userProfile"),
              let authenticator = call.getString("authenticator") else {
            call.reject("Invalid parameters")
            return
        }

        SharedUserClient.instance.authenticateUserWith(profile: UserProfile(identifier: userProfile),
                                                       authenticator: authenticator == "" ? nil : Authenticator(identifier: authenticator),
                                                       delegate: self)

        call.resolve()
    }

    // MARK: - AuthenticationDelegate methods

    public func userClient(_ userClient: UserClient, didStartAuthenticationForUser user: UserProfile, authenticator: Authenticator?) {
        notifyListeners(event: "onAuthStart", data: ["user": user.identifier, "authenticator": authenticator?.identifier ?? ""])
    }

    public func userClient(_ userClient: UserClient, didReceivePinChallenge challenge: PinChallenge) {
        notifyListeners(event: "onPinChallenge", data: ["challenge": challenge.description])
    }

    public func userClient(_ userClient: UserClient, didReceiveBiometricChallenge challenge: BiometricChallenge) {
        notifyListeners(event: "onBiometricChallenge", data: ["challenge": challenge.description])
    }

    public func userClient(_ userClient: UserClient, didReceiveCustomAuthFinishAuthenticationChallenge challenge: CustomAuthFinishAuthenticationChallenge) {
        notifyListeners(event: "onCustomAuthChallenge", data: ["challenge": challenge.description])
    }

    public func userClient(_ userClient: UserClient, didAuthenticateUser user: UserProfile, authenticator: Authenticator?, info: [AnyHashable : Any]) {
        notifyListeners(event: "onAuthSuccess", data: ["user": user.identifier, "authenticator": authenticator?.identifier ?? ""])
    }

